var doc = Document;
return Connector.WithTransaction(doc, () => {
  // Setup only: a wall in a group, placed twice. A real task starts at step 1
  // with instances that already exist.
  var level = Autodesk.Revit.DB.Level.Create(doc, 50.0);
  var wall = Autodesk.Revit.DB.Wall.Create(doc,
      Autodesk.Revit.DB.Line.CreateBound(new Autodesk.Revit.DB.XYZ(400, 0, 0), new Autodesk.Revit.DB.XYZ(410, 0, 0)),
      level.Id, false);
  doc.Regenerate();
  var group1 = doc.Create.NewGroup(new System.Collections.Generic.List<Autodesk.Revit.DB.ElementId> { wall.Id });
  doc.Regenerate();
  var group2 = doc.Create.PlaceGroup(new Autodesk.Revit.DB.XYZ(400, 300, 0), group1.GroupType);
  doc.Regenerate();
  var group2Id = group2.Id;

  // 1. Ungroup the instance to change. There is no group edit mode in the API;
  //    editing a member in place is refused once two or more instances exist.
  //    Ungrouped members are ordinary loose elements.
  var looseIds = group1.UngroupMembers();

  // 2. Edit the loose elements.
  Autodesk.Revit.DB.ElementId looseWallId = null;
  foreach (var id in looseIds) { if (doc.GetElement(id) is Autodesk.Revit.DB.Wall) looseWallId = id; }
  var lc = (doc.GetElement(looseWallId) as Autodesk.Revit.DB.Wall).Location as Autodesk.Revit.DB.LocationCurve;
  lc.Curve = Autodesk.Revit.DB.Line.CreateBound(new Autodesk.Revit.DB.XYZ(403, 0, 0), new Autodesk.Revit.DB.XYZ(413, 0, 0));
  doc.Regenerate();

  // 3. Regroup them: NewGroup mints a new GroupType that reflects the edit.
  var newType = doc.Create.NewGroup(new System.Collections.Generic.List<Autodesk.Revit.DB.ElementId> { looseWallId }).GroupType;
  doc.Regenerate();

  // 4. Reassign every other instance to the new type (Group.GroupType is
  //    settable). This is what propagates the edit.
  var newTypeId = newType.Id;
  (doc.GetElement(group2Id) as Autodesk.Revit.DB.Group).GroupType = doc.GetElement(newTypeId) as Autodesk.Revit.DB.GroupType;
  doc.Regenerate();

  // Revit re-creates a reassigned instance's members: re-fetch ids, never
  // reuse ones captured before the reassignment.
  var memberIds = (doc.GetElement(group2Id) as Autodesk.Revit.DB.Group).GetMemberIds();
  return new { newGroupTypeId = newTypeId.Value, memberCount = memberIds.Count };
});
